content.solution_code:
class SmartLight {
  #brightnessLevel;
  #isOn;

  constructor() {
    this.#brightnessLevel = 0;
    this.#isOn = false;
  }

  turnOn() {
    this.#isOn = true;
  }

  turnOff() {
    this.#isOn = false;
  }

  setBrightness(level) {
    this.#brightnessLevel = Math.max(0, Math.min(100, level));
  }

  getStatus() {
    return `Light is ${this.#isOn ? 'ON' : 'OFF'} at ${this.#brightnessLevel}% brightness.`;
  }
}

